var currentLang = 'en';

function t(key) {
  var d = langData[currentLang];
  if (d && d[key] !== undefined) return d[key];
  if (langData.en[key] !== undefined) return langData.en[key];
  return key;
}

function setLang(code) {
  if (langData[code]) {
    currentLang = code;
    state.lang = code;
    applyLang();
    save();
  }
}

function genId() {
  return '' + (state.nextId++);
}

var state = {
  notes: [], boards: [], studySets: [], trash: [],
  activeNoteId: null, activeBoardId: null, activeStudySetId: null,
  view: 'notes', theme: 'dark', lang: 'en',
  nextId: Date.now(), _exportCount: 0, _triggeredMilestones: [],
  diaryPwdHash: '', diaryRecoveryCode: '', _welcomed: false
};

function save() {
  try {
    localStorage.setItem('mibabel_state', JSON.stringify(state));
  } catch(e) {}
}

function load() {
  try {
    var d = localStorage.getItem('mibabel_state');
    if (d) {
      var parsed = JSON.parse(d);
      for (var k in parsed) state[k] = parsed[k];
    }
  } catch(e) {}
  if (!state._triggeredMilestones) state._triggeredMilestones = [];
  if (!state.trash) state.trash = [];
  if (state.nextId < Date.now()) state.nextId = Date.now();
  if (!state.notes) state.notes = [];
  if (!state.boards) state.boards = [];
  if (!state.studySets) state.studySets = [];
  if (state.lang && langData[state.lang]) currentLang = state.lang;
  cleanupTrash();
}

function escapeHtml(str) {
  if (!str) return '';
  var div = document.createElement('div');
  div.appendChild(document.createTextNode(str));
  return div.innerHTML;
}

function parseNoteLinks(str) {
  if (!str) return '';
  var r = str;
  r = r.replace(/\[\(([^)]+)\)\]/g, '<a href="#" class="note-link" data-title="$1">$1</a>');
  r = r.replace(/\[\{([^}]+)\}\]/g, '<a href="$1" target="_blank" rel="noopener" class="url-link">$1</a>');
  return r;
}

function renderCardContent(text) {
  if (!text) return '';
  var parts = text.split(/(<img[^>]*>)/g);
  var out = '';
  for (var i = 0; i < parts.length; i++) {
    var part = parts[i];
    if (/^<img[^>]*>$/i.test(part)) {
      if (part.indexOf('class="') !== -1) {
        part = part.replace(/class="([^"]*)"/, 'class="$1 card-list-img"');
      } else {
        part = part.replace(/<img /, '<img class="card-list-img" ');
      }
      out += part;
    } else {
      out += parseNoteLinks(escapeHtml(part));
    }
  }
  return out;
}

function applyTheme() {
  document.body.className = state.theme === 'light' ? 'light' : '';
  var isLight = state.theme === 'light';
  document.getElementById('headerLogo').innerHTML = '<img src="" alt="logo" style="height:32px">';
  document.getElementById('sidebarLogo').innerHTML = '<img src="" alt="logo" style="max-width:120px">';
  var label = document.getElementById('menuThemeLabel');
  if (label) label.textContent = isLight ? t('darkTheme') : t('lightTheme');
}

function toggleTheme() {
  state.theme = state.theme === 'dark' ? 'light' : 'dark';
  applyTheme();
  save();
}

