    boardEmptyText: t('noBoards'),
    diaryEmptyText: t('noContent'),
    cafecitoMsg: t('cafecitoDesc'),
    newNoteTitle: t('newNote'),
    newNoteTitleLabel: t('title'),
    newNotePwdLabel: t('passwordOptional'),
    newNoteNameInput: { placeholder: t('noteTitlePlaceholder') },
    newNotePwdInput: { placeholder: t('leaveEmpty') },
    newNoteCancelBtn: { textContent: t('cancel') },
    newNoteCreateBtn: { textContent: t('create') },
