function renderAll() {
  switch (state.view) {
    case 'notes': renderNotes(); break;
    case 'board': renderBoards(); break;
    case 'diary': renderDiary(); break;
    case 'study': renderStudyContent(); break;
    case 'cafecito': renderCafecito(); break;
    case 'settings': renderSettings(); break;
    case 'trash': renderTrashContent(); break;
  }
  updateFab();
  var panels = document.querySelectorAll('.panel');
  for (var i = 0; i < panels.length; i++) panels[i].classList.remove('active');
  var activePanel = document.getElementById('panel' + state.view.charAt(0).toUpperCase() + state.view.slice(1));
  if (activePanel) activePanel.classList.add('active');
}

function switchView(view) {
  state.view = view;
  save();
  document.getElementById('menuOverlay').classList.remove('open');
  document.getElementById('menuSidebar').classList.remove('open');
  if (view === 'diary') {
    if (state.diaryPwdHash && !diaryUnlocked) {
      diaryUnlockFlow();
      return;
    }
  }
  var backBtn = document.getElementById('headerBackBtn');
  if (view === 'study') {
    if (state.activeStudySetId) {
      backBtn.style.display = '';
    } else {
      backBtn.style.display = 'none';
    }
  } else {
    backBtn.style.display = 'none';
  }
  renderAll();
  renderAll();
}

var diaryUnlocked = false;

function renderNotes() {
  var list = document.getElementById('notesList');
  var content = document.getElementById('noteContent');
  if (!list) return;
  list.innerHTML = '';
  if (state.notes.length === 0) {
    list.innerHTML = '<div style="padding:16px;text-align:center;color:var(--text-sec);font-size:13px">' + t('noNotes') + '</div>';
  }
  for (var i = state.notes.length - 1; i >= 0; i--) {
    var note = state.notes[i];
    var div = document.createElement('div');
    div.className = 'card' + (note.id === state.activeNoteId ? ' active' : '');
    div.dataset.id = note.id;
    var title = note.title || t('noContent');
    var preview = '';
    if (note.content) {
      var txt = note.content.replace(/<[^>]+>/g, '');
      preview = txt.substring(0, 80);
      if (txt.length > 80) preview += '...';
    }
    var lockIcon = note.password ? ' &#128274;' : '';
    var favIcon = note.favorite ? ' &#9733;' : '';
    div.innerHTML = '<h3>' + escapeHtml(title) + lockIcon + favIcon + '</h3><p>' + escapeHtml(preview) + '</p>';
    div.addEventListener('click', function(id) {
      return function() { selectNote(id); };
    }(note.id));
    list.appendChild(div);
  }
  if (state.activeNoteId) {
    var found = false;
    for (var j = 0; j < state.notes.length; j++) {
      if (state.notes[j].id === state.activeNoteId) { found = true; break; }
    }
    if (!found) {
      state.activeNoteId = null;
      save();
    }
  }
  renderNoteContent();
}

function selectNote(id) {
  state.activeNoteId = id;
  save();
  renderNotes();
}

function renderNoteContent() {
  var content = document.getElementById('noteContent');
  if (!state.activeNoteId) {
    content.innerHTML = '<div class="empty-state"><div class="empty-icon">&#128221;</div><p>' + t('selectNote') + '</p></div>';
    return;
  }
  var note = null;
  for (var i = 0; i < state.notes.length; i++) {
    if (state.notes[i].id === state.activeNoteId) { note = state.notes[i]; break; }
  }
  if (!note) {
    content.innerHTML = '<div class="empty-state"><div class="empty-icon">&#128221;</div><p>' + t('selectNote') + '</p></div>';
    return;
  }
  if (note.password && !note._unlocked) {
    content.innerHTML = '<div class="empty-state"><div class="empty-icon">&#128274;</div><p>' + t('protectedNote') + '</p><button class="btn" onclick="unlockNote(\'' + note.id + '\')">' + t('enterPassword') + '</button></div>';
    return;
  }
  var html = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap">';
  html += '<h2 style="flex:1;font-size:18px">' + escapeHtml(note.title || t('noContent')) + '</h2>';
  html += '<button class="btn" onclick="favoriteNote(\'' + note.id + '\')">' + (note.favorite ? t('removeFav') : t('addFav')) + '</button>';
  html += '<button class="btn" onclick="renameNote(\'' + note.id + '\')">' + t('rename') + '</button>';
  html += '<button class="btn btn-danger" onclick="deleteNote(\'' + note.id + '\')">' + t('deleteNote') + '</button>';
  html += '</div>';
  html += '<div class="fmt-toolbar">';
  html += '<button class="fmt-action" onclick="execFmt(\'bold\',\'noteContentArea\')" title="' + t('bold') + '"><b>B</b></button>';
  html += '<button class="fmt-action" onclick="execFmt(\'italic\',\'noteContentArea\')" title="' + t('italic') + '"><i>I</i></button>';
  html += '<button class="fmt-action" onclick="execFmt(\'underline\',\'noteContentArea\')" title="' + t('underline') + '"><u>U</u></button>';
  html += '<span class="fmt-sep"></span>';
  html += '<button class="fmt-action" onclick="execFmt(\'insertUnorderedList\',\'noteContentArea\')" title="' + t('bulletList') + '">&#8226;</button>';
  html += '<button class="fmt-action" onclick="execFmt(\'insertOrderedList\',\'noteContentArea\')" title="' + t('numberedList') + '">1.</button>';
  html += '<span class="fmt-sep"></span>';
  html += '<button class="btn-img" onclick="insertNoteImage()" title="' + t('insertImage') + '">&#128247;</button>';
  html += '</div>';
  html += '<div id="noteContentArea" contenteditable="true" style="flex:1;min-height:200px;padding:12px;border:1px solid var(--border);border-radius:8px;background:var(--input-bg);outline:none;overflow-y:auto">' + note.content + '</div>';
  html += '<input type="file" id="noteImageInput" accept="image/*" style="display:none">';
  html += '<div style="margin-top:8px"><button class="btn btn-primary" onclick="saveNoteContent()">' + t('save') + '</button></div>';
  content.innerHTML = html;
}

function execFmt(cmd, areaId) {
  var area = document.getElementById(areaId);
  if (!area) return;
  area.focus();
  document.execCommand(cmd, false, null);
}

function saveNoteContent() {
  var area = document.getElementById('noteContentArea');
  if (!area) return;
  for (var i = 0; i < state.notes.length; i++) {
    if (state.notes[i].id === state.activeNoteId) {
      state.notes[i].content = area.innerHTML;
      break;
    }
  }
  save();
  renderNoteContent();
}

function insertNoteImage() {
  var input = document.getElementById('noteImageInput');
  if (!input) {
    input = document.createElement('input');
    input.type = 'file';
    input.id = 'noteImageInput';
    input.accept = 'image/*';
    input.style.display = 'none';
    document.body.appendChild(input);
  }
  input.onchange = function() {
    var file = input.files[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) { alert(t('coverTooLarge')); return; }
    var reader = new FileReader();
    reader.onload = function(e) {
      var area = document.getElementById('noteContentArea');
      if (area) {
        area.focus();
        document.execCommand('insertImage', false, e.target.result);
      }
    };
    reader.readAsDataURL(file);
    input.value = '';
  };
  input.click();
}

var _notePwdCallback = null;

function unlockNote(id) {
  _notePwdCallback = function(pwd) {
    for (var i = 0; i < state.notes.length; i++) {
      if (state.notes[i].id === id) {
        if (state.notes[i].password === pwd) {
          state.notes[i]._unlocked = true;
          save();
          renderNotes();
          closeDialog('notePasswordDialog');
          return true;
        }
        return false;
      }
    }
    return false;
  };
  document.getElementById('notePwdInput').value = '';
  document.getElementById('notePwdAlert') && (document.getElementById('notePwdAlert').style.display = 'none');
  showDialog('notePasswordDialog');
}

function createNote() {
  var name = document.getElementById('newNoteNameInput').value.trim();
  if (!name) { alert(t('title') + ' ' + t('cancel').toLowerCase()); return; }
  var note = {
    id: genId(),
    title: name,
    content: '',
    password: document.getElementById('newNotePwdInput').value || '',
    favorite: false,
    _unlocked: true,
    type: 'note',
    createdAt: Date.now()
  };
  state.notes.push(note);
  state.activeNoteId = note.id;
  closeDialog('newNoteDialog');
  document.getElementById('newNoteNameInput').value = '';
  document.getElementById('newNotePwdInput').value = '';
  save();
  renderNotes();
  checkMilestones();
}

function deleteNote(id) {
  for (var i = 0; i < state.notes.length; i++) {
    if (state.notes[i].id === id) {
      var note = state.notes[i];
      if (note.favorite) { alert(t('noteInFavorites') + '\n' + t('unfavoriteToDelete')); return; }
      showConfirm(t('deleteNote') + '?', function() {
        state.trash.push({ type: 'note', id: note.id, title: note.title, data: JSON.parse(JSON.stringify(note)), deletedAt: Date.now() });
        state.notes.splice(i, 1);
        if (state.activeNoteId === id) state.activeNoteId = state.notes.length > 0 ? state.notes[state.notes.length - 1].id : null;
        save();
        renderNotes();
      });
      return;
    }
  }
}

function favoriteNote(id) {
  for (var i = 0; i < state.notes.length; i++) {
    if (state.notes[i].id === id) {
      state.notes[i].favorite = !state.notes[i].favorite;
      save();
      renderNotes();
      return;
    }
  }
}

function renameNote(id) {
  for (var i = 0; i < state.notes.length; i++) {
    if (state.notes[i].id === id) {
      var newName = prompt(t('rename'), state.notes[i].title);
      if (newName && newName.trim()) {
        state.notes[i].title = newName.trim();
        save();
        renderNotes();
      }
      return;
    }
  }
}

function renderBoards() {
  var body = document.getElementById('boardBody');
  if (!body) return;
  var html = '';
  if (state.boards.length === 0) {
    html = '<div class="empty-state"><div class="empty-icon">&#128196;</div><p>' + t('noBoards') + '</p></div>';
  }
  html += '<div style="padding:12px;display:flex;flex-direction:column;height:100%">';
  html += '<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap">';
  html += '<button class="btn btn-primary" onclick="showNewBoardDialog()">+ ' + t('newBoard') + '</button>';
  html += '</div>';
  html += '<div style="overflow-y:auto;flex:1">';
  if (state.boards.length > 0) {
    for (var i = state.boards.length - 1; i >= 0; i--) {
      var board = state.boards[i];
      html += '<div class="card" onclick="selectBoard(\'' + board.id + '\')" style="cursor:pointer;' + (board.id === state.activeBoardId ? 'border-left:3px solid var(--accent);background:var(--item-hover)' : '') + '">';
      html += '<h3>' + escapeHtml(board.name || t('noContent')) + ' ' + (board.password ? '&#128274;' : '') + '</h3>';
      html += '<p>' + ((board.postits ? board.postits.length : 0) + ' ' + t('postit').toLowerCase()) + '</p>';
      html += '</div>';
    }
  }
  html += '</div></div>';
  body.innerHTML = html;
  if (state.activeBoardId) renderBoardView(null);
}

function selectBoard(id) {
  state.activeBoardId = id;
  save();
  renderBoards();
}

function renderBoardView(board) {
  if (!board) {
    for (var i = 0; i < state.boards.length; i++) {
      if (state.boards[i].id === state.activeBoardId) { board = state.boards[i]; break; }
    }
  }
  var body = document.getElementById('boardBody');
  if (!board || !body) return;
  if (board.password && !board._unlocked) {
    body.innerHTML = '<div class="empty-state"><div class="empty-icon">&#128274;</div><p>' + t('protectedBoard') + '</p><button class="btn" onclick="unlockBoard(\'' + board.id + '\')">' + t('enterPassword') + '</button></div>';
    return;
  }
  if (!board.postits) board.postits = [];
  if (!board.connections) board.connections = [];
  var html = '<div class="board-toolbar">';
  html += '<button class="btn btn-primary" onclick="addPostit(\'' + board.id + '\')">+ ' + t('postit') + '</button>';
  html += '<button class="btn" onclick="addBoardTextItem(\'' + board.id + '\')">' + t('addText') + '</button>';
  html += '<button class="btn" onclick="enableBoardConnect(\'' + board.id + '\')">' + t('connect') + '</button>';
  html += '<button class="btn" onclick="selectBoardBg(\'' + board.id + '\')">' + t('bg') + '</button>';
  html += '<button class="btn" onclick="deleteBoard(\'' + board.id + '\')" style="color:#f85149">' + t('deleteBoard') + '</button>';
  html += '<span style="flex:1"></span>';
  html += '<button class="btn" onclick="selectBoard(\'\')">' + t('back') + '</button>';
  html += '</div>';
  var bg = board.bg || 'default';
  html += '<div class="board-canvas" id="boardCanvas" style="background:' + (bg === 'cork' ? '#d4a76a' : bg === 'black' ? '#1a1a1a' : bg === 'green' ? '#2d5a27' : bg === 'white' ? '#f5f5f5' : 'var(--bg)') + ';position:relative;min-height:500px">';
  if (board.postits) {
    for (var j = 0; j < board.postits.length; j++) {
      var p = board.postits[j];
      var color = p.color || 'yellow';
      html += '<div class="postit postit-' + color + '" style="left:' + (p.x || 50) + 'px;top:' + (p.y || 50 + j * 30) + 'px" data-id="' + p.id + '">';
      html += '<button class="postit-del" onclick="deletePostit(\'' + board.id + '\',\'' + p.id + '\')">&times;</button>';
      html += '<div contenteditable="true" onblur="updatePostitContent(\'' + board.id + '\',\'' + p.id + '\',this.innerHTML)" style="min-height:80px;outline:none">' + (p.content || '') + '</div>';
      html += '</div>';
    }
  }
  if (board.connections) {
    for (var k = 0; k < board.connections.length; k++) {
      var conn = board.connections[k];
      html += '<div class="connection-line" id="conn-' + conn.id + '" style="display:none"></div>';
    }
  }
  html += '</div>';
  body.innerHTML = html;
  if (board.connections) {
    for (var k = 0; k < board.connections.length; k++) {
      drawConnection(board.id, board.connections[k]);
    }
  }
}

