    body.innerHTML += '<button class="fmt-action" onclick="execFmt(\'underline\',\'diaryContentArea\')" title="' + t('underline') + '"><u>U</u></button>';
    body.innerHTML += '</div>';
    body.innerHTML += '<div id="diaryContentArea" contenteditable="true" style="flex:1;min-height:200px;padding:12px;border:1px solid var(--border);border-radius:8px;background:var(--input-bg);outline:none;overflow-y:auto">' + (entry.content || '') + '</div>';
