function diaryUnlockFlow() {
  var el = document.getElementById('diaryPwdInput');
  if (el) el.value = '';
  document.getElementById('diaryPwdGroup').style.display = '';
  document.getElementById('diaryOldPwdGroup').style.display = 'none';
  document.getElementById('diaryNewPwdGroup').style.display = 'none';
  document.getElementById('diaryPwdLabel').textContent = t('diaryPwdLabel');
  document.getElementById('diaryPwdTitle').textContent = t('diaryProtected');
  document.getElementById('diaryPwdAlert').style.display = 'none';
  document.getElementById('diaryPwdConfirmBtn').onclick = function() {
    var pwd = document.getElementById('diaryPwdInput').value;
    if (simpleHash(pwd) === state.diaryPwdHash) {
      diaryUnlocked = true;
      closeDialog('diaryPwdDialog');
      renderDiary();
    } else {
      document.getElementById('diaryPwdAlert').textContent = t('diaryPwdAlertWrong');
      document.getElementById('diaryPwdAlert').style.display = '';
    }
  };
  showDialog('diaryPwdDialog');
}

function simpleHash(str) {
  var hash = 0;
  for (var i = 0; i < str.length; i++) {
    var c = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + c;
    hash = hash & hash;
  }
  return '' + hash;
}

